SELECT

FROM sp_subscription_order
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY order_time DESC

SELECT o.*, u.name as user_name, u.avatar as user_avatar, c.name as config_name, c.price as config_price, c.project_num as config_project_num, c.user_num as config_user_num, c.storage as config_storage, c.storage_unit as config_storage_unit, c.duration as config_duration FROM sp_subscription_order o LEFT JOIN users u ON o.user_id = u.id LEFT JOIN sp_subscription_config c ON o.config_id = c.id
AND o.user_id = #{userId}
AND o.status = #{status}
AND o.order_time >= #{startTime}
AND o.order_time <= #{endTime}
ORDER BY o.order_time DESC

